{
  "claims": [
    {
      "anchor": "WAL mode first appeared in SQLite 3.7.0",
      "claim_text": "WAL mode first appeared in SQLite 3.7.0.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P4.S1 states WAL available beginning with version 3.7.0."
    },
    {
      "anchor": "journal_mode=WAL is persistent",
      "claim_text": "journal_mode=WAL is persistent.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P2.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P2.S0 directly states WAL mode is persistent."
    },
    {
      "anchor": "simply closing and reopening a WAL database is not enough to change its page size",
      "claim_text": "Simply closing and reopening a WAL database is not enough to change its page size.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P2.S1", "rel": "entails"},
        {"sid": "P0.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Reopening returns WAL mode (P2.S1), and page_size cannot change in WAL mode (P0.S0)."
    },
    {
      "anchor": "you have to switch back to a rollback journal mode first",
      "claim_text": "To change the page size, you must switch back to a rollback journal mode first.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P0.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P0.S1 states rollback journal mode is required to change page size."
    },
    {
      "anchor": "From version 3.7.0 until 3.22.0, reading a WAL-mode database required write access",
      "claim_text": "From version 3.7.0 until 3.22.0, reading a WAL-mode database required write access.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P3.S1", "rel": "entails"},
        {"sid": "P3.S2", "rel": "entails"},
        {"sid": "P4.S1", "rel": "entails"}
      ],
      "check": {"kind": "version", "left": "3.7.0", "op": "<", "right": "3.22.0"},
      "reasoning": "WAL available from 3.7.0 (P4.S1); write access required (P3.S1) until relaxed at 3.22.0 (P3.S2)."
    },
    {
      "anchor": "SQLite's default page size is 4096 bytes",
      "claim_text": "SQLite's default page size is 4096 bytes.",
      "kind": "direct",
      "sure": true,
      "evidence": [],
      "check": null,
      "reasoning": "No passage states the default page size."
    },
    {
      "anchor": "Converting a database to WAL fails if the VFS does not support the necessary shared-memory primitives",
      "claim_text": "Converting a database to WAL fails if the VFS does not support the necessary shared-memory primitives.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P1.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P1.S2 gives this as an example of conversion not completing."
    },
    {
      "anchor": "in which case the journal_mode pragma returns an error",
      "claim_text": "If conversion to WAL fails, the journal_mode pragma returns an error.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P1.S2", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "P1.S2 says the pragma returns the prior journal mode string, not an error."
    }
  ]
}
